#!/usr/bin/env bash
# wf diff-scoped check: changed files -> areas -> each area's lint/typecheck/test.
# Generated by /wf:setup; edit the AREAS table, not the logic.
set -euo pipefail
BASE="${BASE:-$(git merge-base HEAD origin/main 2>/dev/null || git merge-base HEAD main)}"
mapfile -t CHANGED < <( { git diff --name-only "$BASE"...HEAD; git diff --name-only; git ls-files --others --exclude-standard; } | sort -u)
[ ${#CHANGED[@]} -eq 0 ] && { echo "wf check: nothing changed since $BASE"; exit 0; }

# name|dirs (space-separated, "." = repo root)|lint|typecheck|test
# Commands run from the first dir. {files} = the area's changed files, relative to that dir (omit it to test the whole area).
AREAS=(
  "<name>|<dir>|<lint cmd>|<typecheck cmd>|<test cmd {files}>"
)

fail=0; ran=0
for row in "${AREAS[@]}"; do
  IFS='|' read -r name dirs lint typecheck test <<<"$row"
  read -r -a dirlist <<<"$dirs"; run_in="${dirlist[0]}"
  files=()
  for f in "${CHANGED[@]}"; do
    [ -e "$f" ] || continue
    for d in "${dirlist[@]}"; do
      if [ "$d" = . ] || [[ "$f" == "$d"/* ]]; then
        if [ "$run_in" = . ]; then files+=("$f"); else files+=("${f#"$run_in"/}"); fi; break
      fi
    done
  done
  [ ${#files[@]} -eq 0 ] && continue
  echo "== $name (${#files[@]} files)"; ran=1
  for cmd in "$lint" "$typecheck" "$test"; do
    [ -z "$cmd" ] || [ "$cmd" = none ] && continue
    cmd="${cmd//\{files\}/${files[*]}}"
    echo "-- $cmd"; (cd "$run_in" && eval "$cmd") || { echo "FAIL: $name: $cmd"; fail=1; }
  done
done
[ $ran -eq 0 ] && echo "wf check: no area affected by ${#CHANGED[@]} changed files"
exit $fail
